const ledgerControlSources = `-- name: LedgerControlSources :one
SELECT
    (SELECT COALESCE(sum(i.debit - i.credit), 0) FROM folio_items i
      WHERE i.tenant_id = $1 AND i.property_id = $2 AND i.business_date <= $3::date)::numeric AS folio_balance,
    (SELECT CASE WHEN pr.deposit_release_mode = 'EVERY_DAY'
                 THEN COALESCE((SELECT sum(d.held - d.applied) FROM folio_deposit_state($2, $3::date) d), 0)
                 ELSE COALESCE((SELECT sum(d.held) FROM folio_deposit_state($2, $3::date) d WHERE NOT d.closed), 0)
            END FROM properties pr WHERE pr.id = $2)::numeric AS deposits_held,
    (SELECT pr.deposit_release_mode FROM properties pr WHERE pr.id = $2)::text AS release_mode
`

type LedgerControlSourcesParams struct {
	TenantID   int64
	PropertyID int64
	AsOf       civil.Date
}

type LedgerControlSourcesRow struct {
	FolioBalance decimal.Decimal
	DepositsHeld decimal.Decimal
	ReleaseMode  string
}

// What the control sources of the accounts say as of the date (the same two sums as accounting.ControlSources) and the deposit release mode.
func (q *Queries) LedgerControlSources(ctx context.Context, arg LedgerControlSourcesParams) (LedgerControlSourcesRow, error) {
	row := q.db.QueryRow(ctx, ledgerControlSources, arg.TenantID, arg.PropertyID, arg.AsOf)
	var i LedgerControlSourcesRow
	err := row.Scan(&i.FolioBalance, &i.DepositsHeld, &i.ReleaseMode)
	return i, err
}

